#!/usr/bin/env node
function e(e=process.argv.slice(2)){let t=!1;for(let[n,r]of e.entries()){if(r===`--`)break;if(r===`--quiet=false`||r===`-q=false`||r===`--no-quiet`){t=!1;continue}if(r===`--quiet=true`||r===`-q=true`){t=!0;continue}(r===`--quiet`||r===`-q`)&&(t=e[n+1]!==`false`)}return t}export{e as t};